cd "$(dirname "$0")"; bash vp.sh "$@" | sed 's/a NEW outfit, a fine silk robe with embroidered borders and a small woven \(.*\) pattern, a silk sash with a small jade pendant (a little more ornate than the lowest consort rank, little gold), neat chignon with silver and pearl hairpins and a fresh flower;/[T2 \1];/; s/ (elegant, never poor, little gold), hair in a neat bun with pretty silver hairpins and a fresh flower//; s/same small size at every rank, never covering the forehead or spreading to the brows; the same huadian on all four figures.//; s/Forehead: a small, delicate, refined huadian between the brows, elegant, not large: her signature motif /HD: /; s/Outfit for all four (rank-2 consort (Thuong tai), a little richer than the rank below): //; s/her signature colour family \(.*\) stays the MAIN robe colour/COL \1/'
